/// Borrow block `b` of `img`. `None` past the end of the image.
pub fn block(img: &[u8], b: u32) -> Option<&[u8]> {
    let start = (b as usize).checked_mul(MFS_BLOCK_SIZE)?;
    img.get(start..start.checked_add(MFS_BLOCK_SIZE)?)
}

